CREATE TABLE IF NOT EXISTS families (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255) NOT NULL, contact VARCHAR(255) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS family_users (family_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(family_id,user_id), FOREIGN KEY(family_id) REFERENCES families(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS teachers (user_id BIGINT UNSIGNED PRIMARY KEY, rate DECIMAL(10,2) NULL, rate_unit ENUM('lesson','hour','month') NULL, FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS lesson_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lesson_id BIGINT UNSIGNED NOT NULL, student_id BIGINT UNSIGNED NOT NULL, author_user_id BIGINT UNSIGNED NULL, summary TEXT NOT NULL, next_step TEXT NULL, approved_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(lesson_id) REFERENCES lessons(id), FOREIGN KEY(student_id) REFERENCES students(id), FOREIGN KEY(author_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS invoices (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, participant_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(10,2) NOT NULL, due_at DATETIME NOT NULL, status ENUM('draft','pending','paid','cancelled','refunded','manual_review') NOT NULL DEFAULT 'draft', payment_comment VARCHAR(255) NULL, paid_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(participant_id) REFERENCES lesson_participants(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, invoice_id BIGINT UNSIGNED NOT NULL, external_operation_id VARCHAR(255) NULL UNIQUE, amount DECIMAL(10,2) NOT NULL, status ENUM('confirmed','manual_review') NOT NULL, confirmed_by BIGINT UNSIGNED NULL, confirmed_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(invoice_id) REFERENCES invoices(id), FOREIGN KEY(confirmed_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS exceptions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, type VARCHAR(100) NOT NULL, severity ENUM('info','warning','critical') NOT NULL DEFAULT 'warning', title VARCHAR(255) NOT NULL, details TEXT NULL, status ENUM('open','in_progress','resolved') NOT NULL DEFAULT 'open', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_key VARCHAR(255) NOT NULL UNIQUE, channel ENUM('telegram','email') NOT NULL, recipient VARCHAR(255) NOT NULL, payload JSON NOT NULL, due_at DATETIME NOT NULL, status ENUM('pending','leased','sent','retry','manual_review') NOT NULL DEFAULT 'pending', attempts INT UNSIGNED NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;